shell_commands.command:
patch -p0 <<'PATCH'
*** tests/src/unit-udt.cpp.orig
--- tests/src/unit-udt.cpp
***************
*** 18,25 ****
--- 18,27 ----
      using namespace nlohmann::literals; // NOLINT(google-build-using-namespace)
  #endif

+ #include <cstdint>
+ #include <limits>
  #include <map>
  #include <memory>
  #include <string>
  #include <utility>
***************
*** 861,864 ****
--- 863,897 ----
      json const j = vec;
  }

+ TEST_CASE_TEMPLATE("enum serialization preserves underlying signedness" * doctest::test_suite("udt"), T,
+                    std::int8_t, std::uint8_t, std::int16_t, std::uint16_t,
+                    std::int32_t, std::uint32_t, std::int64_t, std::uint64_t)
+ {
+     enum class scoped_enum : T {};
+     enum unscoped_enum : T {};
+ 
+     for (const T value : {std::numeric_limits<T>::min(), T(0), T(1),
+                          T(std::numeric_limits<T>::max() / 2 + 1),
+                          T(std::numeric_limits<T>::max() - 1), std::numeric_limits<T>::max()})
+     {
+         const auto scoped = static_cast<scoped_enum>(value);
+         const auto unscoped = static_cast<unscoped_enum>(value);
+         const json j_scoped = scoped;
+         json j_unscoped = "previous value";
+         j_unscoped = unscoped;
+ 
+         for (const auto& j : {j_scoped, j_unscoped})
+         {
+             CHECK(j.is_number_integer());
+             CHECK(j.is_number_unsigned() == !std::numeric_limits<T>::is_signed);
+             CHECK(j == json(value));
+             CHECK(j.template get<T>() == value);
+             CHECK(to_string(j) == std::to_string(value));
+             if (value > 0)
+             {
+                 CHECK(j > 0u);
+             }
+         }
+         CHECK(j_scoped.template get<scoped_enum>() == scoped);
+         CHECK(j_unscoped.template get<unscoped_enum>() == unscoped);
+     }
+ }
+ 
  DOCTEST_GCC_SUPPRESS_WARNING_POP
PATCH
cd /testbed/build && cmake .. > /testbed/build/enum-configure.log && make test-udt_cpp11 > /testbed/build/enum-build.log && ./tests/test-udt_cpp11 --test-case='enum serialization preserves underlying signedness*' > /testbed/build/enum-before.log; result=$?; tail -22 /testbed/build/enum-before.log 2>/dev/null; if [ "$result" -ne 0 ] && [ ! -f /testbed/build/enum-before.log ]; then tail -40 /testbed/build/enum-build.log; fi; exit "$result"

python3 - <<'PY'
from pathlib import Path
path = Path('tests/src/unit-udt.cpp')
text = path.read_text()
text = text.replace('#include <map>\n', '#include <cstdint>\n#include <limits>\n#include <map>\n', 1)
marker = 'DOCTEST_GCC_SUPPRESS_WARNING_POP\n'
assert text.count(marker) == 1
text = text.replace(marker, '''TEST_CASE_TEMPLATE("enum serialization preserves underlying signedness" * doctest::test_suite("udt"), T,
                   std::int8_t, std::uint8_t, std::int16_t, std::uint16_t,
                   std::int32_t, std::uint32_t, std::int64_t, std::uint64_t)
{
    enum class scoped_enum : T {};
    enum unscoped_enum : T {};

    for (const T value : {std::numeric_limits<T>::min(), T(0), T(1),
                         T(std::numeric_limits<T>::max() / 2 + 1),
                         T(std::numeric_limits<T>::max() - 1), std::numeric_limits<T>::max()})
    {
        const auto scoped = static_cast<scoped_enum>(value);
        const auto unscoped = static_cast<unscoped_enum>(value);
        const json j_scoped = scoped;
        json j_unscoped = "previous value";
        j_unscoped = unscoped;

        for (const auto& j : {j_scoped, j_unscoped})
        {
            CHECK(j.is_number_integer());
            CHECK(j.is_number_unsigned() == !std::numeric_limits<T>::is_signed);
            CHECK(j == json(value));
            CHECK(j.template get<T>() == value);
            CHECK(to_string(j) == std::to_string(value));
            if (value > 0)
            {
                CHECK(j > 0u);
            }
        }
        CHECK(j_scoped.template get<scoped_enum>() == scoped);
        CHECK(j_unscoped.template get<unscoped_enum>() == unscoped);
    }
}

''' + marker)
path.write_text(text)
PY
cd /testbed/build && make test-udt_cpp11 > /testbed/build/enum-build.log && ./tests/test-udt_cpp11 --test-case='enum serialization preserves underlying signedness*' > /testbed/build/enum-before.log; result=$?; tail -24 /testbed/build/enum-before.log; exit "$result"

